<?php
declare(strict_types=1);define('_GNUBOARD_',true);
require __DIR__.'/../../bridge/inline-edit.php';require __DIR__.'/../../bridge/youtube-catalog.php';
function ny_video_id(string $url):?string{parse_str((string)parse_url($url,PHP_URL_QUERY),$q);return $q['v']??null;}
function verify(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$db->exec("CREATE TABLE noa_documents(doc_key TEXT,kind TEXT,payload TEXT,revision INT);CREATE TABLE noa_catalog_aliases(batch_id TEXT,alias_key TEXT,entity_id TEXT);CREATE TABLE noa_catalog_batches(batch_id TEXT,status TEXT,applied_at TEXT);CREATE TABLE noa_catalog_songs(song_id TEXT,identity_json TEXT,genre_id TEXT,ep TEXT,language TEXT,version_name TEXT);CREATE TABLE noa_catalog_versions(batch_id TEXT,entity_id TEXT,entity_type TEXT,fields_json TEXT,public_verified INT);INSERT INTO noa_catalog_batches VALUES('b','applied','2026-10-27');");
$insert=$db->prepare('INSERT INTO noa_documents VALUES(?,?,?,1)');$sourceUnread=str_repeat('a',64);$sourceLimits=str_repeat('b',64);$alias=str_repeat('c',64);
foreach([['story:unread','미전송(Unread)','unread00001'],['story:bloom','BLOOM','bloom000001'],['story:limits','NO LIMITS','nolimit0001'],['catalog:'.$sourceUnread,'미전송(Unread) | 쓰고 지워도 끝내 보내지 못한 말','unread00001'],['catalog:'.$sourceLimits,'NO LIMITS | 남이 정한 기준을 지우고 진짜 나를 찾다','nolimit0001']] as [$key,$title,$video]){
 $doc=['title'=>$title,'genreId'=>'your-story','visibility'=>'public','body'=>['confirmedTitle'=>$title,'youtubeUrl'=>'https://www.youtube.com/watch?v='.$video,'lyricsBlock'=>'보존 가사','sunoPrompt'=>'보존 프롬프트']];if(str_starts_with($key,'story:'))$doc=nup_normalize($doc,'story');$insert->execute([$key,'story',json_encode($doc)]);
}
$db->prepare('INSERT INTO noa_catalog_aliases VALUES(?,?,?)')->execute(['b','story:unread',$alias]);
$id=str_repeat('1',24);$keys=[$alias,'story:unread','story:bloom','story:limits',$sourceUnread,$sourceLimits];$members=array_map(fn($key)=>['key'=>$key],$keys);$members[0]['note']='retain member metadata';$list=nup_normalize(['title'=>'2026년 제2회 AMT AI 작곡대회 | K-POP','genreId'=>'your-story','customPlaylistId'=>$id,'body'=>['members'=>$members]],'playlist');$insert->execute(['playlist:custom:'.$id,'playlist',json_encode($list)]);
$before=$db->query('SELECT * FROM noa_documents ORDER BY doc_key')->fetchAll(PDO::FETCH_ASSOC);
$pool=nup_song_pool($db);$unique=nup_unique_members($members,$pool);verify(count($unique)===5&&$unique[0]===$members[0],'only exact canonical aliases normalize; preserve distinct documents and first member metadata');
try{nup_validate_members($db,$list);throw new RuntimeException('duplicate accepted');}catch(InvalidArgumentException $e){verify($e->getMessage()==='member_duplicate','writer rejects repeat canonical owner');}
$resolved=nie_resolve($db,['type'=>'playlist','id'=>$id]);verify($resolved['fields']['members']===$unique,'common editor offers a duplicate-free member list');$patched=nup_patch($resolved['payload'],'playlist',['members'=>$unique]);nup_validate_members($db,$patched);verify($patched['body']['members']===$unique,'normalized list can be saved through existing writer');
$videos=[];foreach(['unread00001','unreadshort'] as $video)$videos[$video]=['status'=>['privacyStatus'=>'private','embeddable'=>false],'match'=>['songId'=>$alias],'snippet'=>['title'=>'PRIVATE_PROVIDER_TITLE']];
$catalog=ny_listener_catalog($db,true,nie_overrides($db));$rows=ny_complete_catalog_rows([],$videos,$catalog);verify(count($rows)===6,'six source rows reproduce duplicate list');$identities=[];foreach($rows as $row)$identities[$row['browseIdentity']??$row['canonicalRecordKey']??$row['orderKey']]=true;verify(count($identities)===3,'same explicit videos resolve to three browse identities');
foreach(['unread00001','unreadshort','bloom000001','nolimit0001','PRIVATE_PROVIDER_TITLE'] as $secret)verify(!str_contains(json_encode($rows),$secret),'private source metadata not serialized');
verify($db->query('SELECT * FROM noa_documents ORDER BY doc_key')->fetchAll(PDO::FETCH_ASSOC)===$before,'all original documents and playlist payloads remain unchanged on read');
$different=$catalog;$different[$sourceUnread]['genre']='cover-reborn';$different[$sourceLimits]['ep']='2';$different=ny_browse_catalog($different);verify(!isset($different[$sourceUnread]['browseIdentity'])&&!isset($different[$sourceLimits]['browseIdentity']),'different versions and classifications never collapse');
$rejected=ny_browse_catalog($catalog,['unread00001'=>['match'=>['status'=>'rejected']]]);verify(!isset($rejected[$sourceUnread]['browseIdentity']),'rejected links never establish shared identity');
$sameTitle=['one'=>['key'=>'one','title'=>'동명곡','genre'=>'your-story','kind'=>'video','canonicalVideo'=>'one00000001'],'two'=>['key'=>'two','title'=>'동명곡','genre'=>'your-story','kind'=>'video','canonicalVideo'=>'two00000001']];verify(ny_browse_catalog($sameTitle)===$sameTitle,'same titles are not identity evidence');
$music=[];$documents=[];foreach($before as $source){if($source['kind']==='playlist')continue;$d=json_decode($source['payload'],true);$key=$source['doc_key'];$documents[$key]=$d;$music[]=['key'=>$key,'title'=>$d['title'],'genre'=>'your-story','kind'=>'story'];}
$projection=noa_music_browse_project($music,$documents);verify(count($projection)===5&&count(array_unique(array_column($projection,'browseIdentity')))===2,'MUSIC preserves five records and marks the two duplicate pairs');verify(!str_contains(json_encode($projection),'unread00001'),'MUSIC grouping does not expose private video identifiers');
$pair=array_slice($music,0,1);$pair[]=$pair[0];$pair[1]['key']='story:different-recording';$documents['story:different-recording']=$documents[$pair[0]['key']];$pair[0]['audioSha']=str_repeat('a',64);$pair[1]['audioSha']=str_repeat('b',64);verify(!array_filter(noa_music_browse_project($pair,$documents),fn($r)=>isset($r['browseIdentity'])),'different verified audio files remain distinct');
unset($pair[0]['audioSha'],$pair[1]['audioSha']);$documents[$pair[0]['key']]['body']['sunoShareUrl']='https://suno.com/song/first';$documents['story:different-recording']['body']['sunoShareUrl']='https://suno.com/song/second';verify(!array_filter(noa_music_browse_project($pair,$documents),fn($r)=>isset($r['browseIdentity'])),'different Suno recordings remain distinct');
@mkdir('workspace-proof/candidate',0777,true);file_put_contents('workspace-proof/candidate/collection-duplicates.json',json_encode(['rows'=>$rows,'order'=>['playlists'=>[['id'=>$id,'group'=>'story','title'=>$list['title'],'keys'=>$keys]]]],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT));
echo "COLLECTION_SIX_TO_THREE_CANONICAL_ALIASES_SOURCE_VIDEO_PRIVATE_BOUNDARY_NO_DATA_LOSS_OK\n";
